// tmx/mx/solatcpretransmission/Mx_SolaTcpRetransmission_v1_11_Server.c
/*
 * TMX Group Sola Tcp Retransmission
 *
 * Generated from the binary model. Every record is a run of fields, and esbmc checks two
 * claims of each, for every value its bytes can take rather than for chosen ones: that any
 * record written to the wire and read back is that record, and that any bytes read off the
 * wire and written back are those bytes. Each takes exactly the record's width, and no
 * write or read leaves the buffer it is made on.
 *
 * A field is the bytes it occupies. Nothing is read as an integer, so nothing is read in a
 * byte order, and no rule stated here depends on a value.
 *
 * Check the whole file:   esbmc <file>
 * Check one record:       esbmc <file> --function check_<record>
 *
 * Built with -DCONCRETE it is an ordinary program any C compiler runs: the bytes the
 * checker would choose are drawn from four patterns instead, so the definition can be
 * tried without the checker. That run is a test, and the checker's is the claim.
 *
 * What this definition does not state, and the model does:
 *   - a run filling what frames it
 *   - the dispatch that chooses a message by its type
 *   - a Composite rule
 *   - a run counted by a field
 *
 * License: MIT No Attribution
 */

#include <assert.h>
#include <stddef.h>
#include <stdint.h>

/* ---- Any byte ---------------------------------------------------------------- */

#ifdef CONCRETE

/* which pattern the bytes are drawn from, and how many have been drawn */
static unsigned pattern;
static size_t drawn;

/* a byte of the pattern: zero, a space, every bit set, or one more than the last */
static uint8_t arbitrary(void) {
  drawn++;

  switch (pattern) {
    case 0: return 0;
    case 1: return 32;
    case 2: return 255;
    default: return (uint8_t)(drawn % 256);
  }
}

#else

/* declared and never defined: a value the checker chooses */
unsigned char __VERIFIER_nondet_uchar(void);

/* a byte nobody chose, so what holds of it holds of all of them */
static uint8_t arbitrary(void) {
  return __VERIFIER_nondet_uchar();
}

#endif

/* ---- Message Header: 11 bytes ------------------------------------------------ */

/* Standard Hsvf message header */
typedef struct {
  uint8_t sequence_number[9];  /* bytes 0 to 8 */
  uint8_t message_type[2];     /* bytes 9 to 10 */
} MessageHeader;

/* any Message Header at all: every byte one the checker chooses */
static void any_message_header(MessageHeader *record) {
  for (size_t i = 0; i < 9; i++) { record->sequence_number[i] = arbitrary(); }
  for (size_t i = 0; i < 2; i++) { record->message_type[i] = arbitrary(); }
}

/* Message Header to the wire: 11 bytes from at, returning where the next byte goes */
static size_t encode_message_header(const MessageHeader *record, uint8_t *wire, size_t at) {
  for (size_t i = 0; i < 9; i++) { wire[at++] = record->sequence_number[i]; }
  for (size_t i = 0; i < 2; i++) { wire[at++] = record->message_type[i]; }

  return at;
}

/* Message Header off the wire: 11 bytes from at, returning where the next byte lies */
static size_t decode_message_header(MessageHeader *record, const uint8_t *wire, size_t at) {
  for (size_t i = 0; i < 9; i++) { record->sequence_number[i] = wire[at++]; }
  for (size_t i = 0; i < 2; i++) { record->message_type[i] = wire[at++]; }

  return at;
}

/* what was read of Message Header is what was written, byte for byte */
static void equal_message_header(const MessageHeader *read, const MessageHeader *written) {
  for (size_t i = 0; i < 9; i++) { assert(read->sequence_number[i] == written->sequence_number[i]); }
  for (size_t i = 0; i < 2; i++) { assert(read->message_type[i] == written->message_type[i]); }
}

/* Message Header: written and read back, then read and written back */
static void check_message_header(void) {
  MessageHeader sent;
  MessageHeader got;
  uint8_t wire[11];
  uint8_t again[11];

  any_message_header(&sent);
  assert(encode_message_header(&sent, wire, 0) == 11);
  assert(decode_message_header(&got, wire, 0) == 11);
  equal_message_header(&got, &sent);

  for (size_t i = 0; i < 11; i++) { wire[i] = arbitrary(); }
  assert(decode_message_header(&got, wire, 0) == 11);
  assert(encode_message_header(&got, again, 0) == 11);
  for (size_t i = 0; i < 11; i++) { assert(again[i] == wire[i]); }
}

/* ---- Error Message: 84 bytes ------------------------------------------------- */

/* Error Message */
typedef struct {
  uint8_t error_code[4];  /* bytes 0 to 3 */
  uint8_t error_msg[80];  /* bytes 4 to 83 */
} ErrorMessage;

/* any Error Message at all: every byte one the checker chooses */
static void any_error_message(ErrorMessage *record) {
  for (size_t i = 0; i < 4; i++) { record->error_code[i] = arbitrary(); }
  for (size_t i = 0; i < 80; i++) { record->error_msg[i] = arbitrary(); }
}

/* Error Message to the wire: 84 bytes from at, returning where the next byte goes */
static size_t encode_error_message(const ErrorMessage *record, uint8_t *wire, size_t at) {
  for (size_t i = 0; i < 4; i++) { wire[at++] = record->error_code[i]; }
  for (size_t i = 0; i < 80; i++) { wire[at++] = record->error_msg[i]; }

  return at;
}

/* Error Message off the wire: 84 bytes from at, returning where the next byte lies */
static size_t decode_error_message(ErrorMessage *record, const uint8_t *wire, size_t at) {
  for (size_t i = 0; i < 4; i++) { record->error_code[i] = wire[at++]; }
  for (size_t i = 0; i < 80; i++) { record->error_msg[i] = wire[at++]; }

  return at;
}

/* what was read of Error Message is what was written, byte for byte */
static void equal_error_message(const ErrorMessage *read, const ErrorMessage *written) {
  for (size_t i = 0; i < 4; i++) { assert(read->error_code[i] == written->error_code[i]); }
  for (size_t i = 0; i < 80; i++) { assert(read->error_msg[i] == written->error_msg[i]); }
}

/* Error Message: written and read back, then read and written back */
static void check_error_message(void) {
  ErrorMessage sent;
  ErrorMessage got;
  uint8_t wire[84];
  uint8_t again[84];

  any_error_message(&sent);
  assert(encode_error_message(&sent, wire, 0) == 84);
  assert(decode_error_message(&got, wire, 0) == 84);
  equal_error_message(&got, &sent);

  for (size_t i = 0; i < 84; i++) { wire[i] = arbitrary(); }
  assert(decode_error_message(&got, wire, 0) == 84);
  assert(encode_error_message(&got, again, 0) == 84);
  for (size_t i = 0; i < 84; i++) { assert(again[i] == wire[i]); }
}

